const D50: []const f32 = (&.{ @floatCast((@as(f64, @floatCast(0.3457)) / @as(f64, @floatCast(0.3585)))), 1.0, @floatCast((((@as(f64, @floatCast(1.0)) - @as(f64, @floatCast(0.3457))) - @as(f64, @floatCast(0.3585))) / @as(f64, @floatCast(0.3585)))) });
