const bits = bun.bits;

pub fn UnboundedColorGamut(comptime T: type) type {
        return struct {

pub fn inGamut(unused_color: *const T) bool {
            _ = &unused_color;
            return true;
    }

pub fn clip(color_val: *const T) T {
            return color_val.*;
    }
};
