pub fn DefineColorspace(comptime T: type, comptime ChannelTypeMap: anytype) type {
        const fields: []const std.builtin.Type.StructField = @typeInfo(T).@"struct".fields;
        const a = (if (@typeInfo(@TypeOf(fields[0])) == .@"enum" or @typeInfo(@TypeOf(fields[0])) == .@"union") @tagName(fields[0]) else fields[0].name);
        const b = (if (@typeInfo(@TypeOf(fields[1])) == .@"enum" or @typeInfo(@TypeOf(fields[1])) == .@"union") @tagName(fields[1]) else fields[1].name);
        const c = (if (@typeInfo(@TypeOf(fields[2])) == .@"enum" or @typeInfo(@TypeOf(fields[2])) == .@"union") @tagName(fields[2]) else fields[2].name);
        const alpha: []const u8 = "alpha";
        if ((!@hasField(T, "alpha"))) {
            _ = @compileError("A Colorspace must define an alpha field");
        }
        if ((!@hasField(@TypeOf(ChannelTypeMap), a))) {
            _ = @compileError(("A Colorspace must define a field for each channel, missing: " ++ a));
        }
        if ((!@hasField(@TypeOf(ChannelTypeMap), b))) {
            _ = @compileError(("A Colorspace must define a field for each channel, missing: " ++ b));
        }
        if ((!@hasField(@TypeOf(ChannelTypeMap), c))) {
            _ = @compileError(("A Colorspace must define a field for each channel, missing: " ++ c));
        }
        return struct {
        pub fn components(color_val: *const T) struct { f32, f32, f32, f32 } {
            return .{
                @field(color_val, a),
                @field(color_val, b),
                @field(color_val, c),
                @field(color_val, alpha),
            };
        }

        pub fn channels(_: *const T) struct { []const u8, []const u8, []const u8 } {
            return .{ a, b, c };
        }

        pub fn types(_: *const T) struct { ChannelType, ChannelType, ChannelType } {
            return .{
                @field(ChannelTypeMap, a),
                @field(ChannelTypeMap, b),
                @field(ChannelTypeMap, c),
            };
        }

        pub fn resolveMissing(color_val: *const T) T {
            var result: T = color_val.*;
            @field(result, a) = if (std.math.isNan(@field(color_val, a))) 0.0 else @field(color_val, a);
            @field(result, b) = if (std.math.isNan(@field(color_val, b))) 0.0 else @field(color_val, b);
            @field(result, c) = if (std.math.isNan(@field(color_val, c))) 0.0 else @field(color_val, c);
            @field(result, alpha) = if (std.math.isNan(@field(color_val, alpha))) 0.0 else @field(color_val, alpha);
            return result;
        }

        pub fn resolve(color_val: *const T) T {
            var resolved = resolveMissing(color_val);
            if (!resolved.inGamut()) {
                resolved = mapGamut(T, resolved);
            }
            return resolved;
        }
    };
}

pub fn BoundedColorGamut(comptime T: type) type {
        const fields: []const std.builtin.Type.StructField = std.@"meta".fields(T);
        const a = (if (@typeInfo(@TypeOf(fields[0])) == .@"enum" or @typeInfo(@TypeOf(fields[0])) == .@"union") @tagName(fields[0]) else fields[0].name);
        const b = (if (@typeInfo(@TypeOf(fields[1])) == .@"enum" or @typeInfo(@TypeOf(fields[1])) == .@"union") @tagName(fields[1]) else fields[1].name);
        const c = (if (@typeInfo(@TypeOf(fields[2])) == .@"enum" or @typeInfo(@TypeOf(fields[2])) == .@"union") @tagName(fields[2]) else fields[2].name);
        return struct {

pub fn inGamut(color_val: *const T) bool {
            return ((((((@field(color_val, a) >= 0.0) and (@field(color_val, a) <= 1.0)) and (@field(color_val, b) >= 0.0)) and (@field(color_val, b) <= 1.0)) and (@field(color_val, c) >= 0.0)) and (@field(color_val, c) <= 1.0));
    }

pub fn clip(color_val: *const T) T {
            var result: T = color_val.*;
            _ = &result;
            @field(result, a) = bun.clamp(@field(color_val, a), 0.0, 1.0);
            @field(result, b) = bun.clamp(@field(color_val, b), 0.0, 1.0);
            @field(result, c) = bun.clamp(@field(color_val, c), 0.0, 1.0);
            result.alpha = bun.clamp(color_val.alpha, 0.0, 1.0);
            return result;
    }
};
}

pub fn DeriveInterpolate(comptime T: type, comptime a: []const u8, comptime b: []const u8, comptime c: []const u8) type {
        if ((!@hasField(T, a))) {
            _ = @compileError(("Missing field: " ++ a));
        }
        if ((!@hasField(T, b))) {
            _ = @compileError(("Missing field: " ++ b));
        }
        if ((!@hasField(T, c))) {
            _ = @compileError(("Missing field: " ++ c));
        }
        return struct {

pub fn fillMissingComponents(color_val: *T, other: *T) void {
            if (std.math.isNan(@field(color_val, a))) {
                @field(color_val, a) = @field(other, a);
            }
            if (std.math.isNan(@field(color_val, b))) {
                @field(color_val, b) = @field(other, b);
            }
            if (std.math.isNan(@field(color_val, c))) {
                @field(color_val, c) = @field(other, c);
            }
            if (std.math.isNan(color_val.alpha)) {
                color_val.alpha = other.alpha;
            }
    }

pub fn interpolate(color_val: *const T, p1: f32, other: *const T, p2: f32) T {
            var result: T = undefined;
            _ = &result;
            @field(result, a) = ((@field(color_val, a) * p1) + (@field(other, a) * p2));
            @field(result, b) = ((@field(color_val, b) * p1) + (@field(other, b) * p2));
            @field(result, c) = ((@field(color_val, c) * p1) + (@field(other, c) * p2));
            result.alpha = ((color_val.alpha * p1) + (other.alpha * p2));
            return result;
    }
};
}

pub fn RecangularPremultiply(comptime T: type, comptime a: []const u8, comptime b: []const u8, comptime c: []const u8) type {
        if ((!@hasField(T, a))) {
