                @field(self, b) = (@field(self, b) / self.alpha);
                @field(self, c) = (@field(self, c) / self.alpha);
                self.alpha = (self.alpha * alpha_multiplier);
            }
    }
};
}

pub fn PolarPremultiply(comptime T: type, comptime a: []const u8, comptime b: []const u8) type {
